# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, C, J, A, D_ = "Lucas", "Camilo", "Jairo", "Amparo", "Daniela"
D = [
("#", "Escena 1 · Lunes, 14:40 · Aeropuerto El Dorado y taxi hacia el norte de Bogotá", "장면 1 · 월요일 오후 2시 40분 · 엘도라도 공항, 보고타 북쪽으로 가는 택시"),
(None, "Lunes 21 de abril. Lucas sale de la terminal con una maleta pequeña y una caja de muestras. El cielo es gris y cae una llovizna fina. Hace catorce grados. Ha dejado a Amparo en Monterrey, con las pruebas de colocación en la obra de San Pedro.", "4월 21일 월요일. 루카스가 작은 여행 가방과 샘플 상자 하나를 들고 터미널을 나선다. 하늘은 잿빛이고 가는 이슬비가 내린다. 기온은 14도. 암파로는 산페드로 현장의 시공 테스트를 맡아 몬테레이에 남았다."),
(J, "Buenas tardes, sumercé. ¿Para dónde lo llevo?", "안녕하세요, 손님. 어디로 모실까요?"),
(L, "Buenas tardes. A este hotel, en la calle noventa y tres, por favor.", "안녕하세요. 93번가에 있는 이 호텔로 부탁해요."),
(J, "Con mucho gusto. Permítame la maleta. ¿Y esa caja tan pesada? ¿Trae piedras?", "기꺼이요. 가방 주세요. 그런데 이 무거운 상자는요? 돌이라도 가져오셨어요?"),
(L, "Casi. Son muestras de baldosas. Cerámica española.", "거의요. 타일 샘플이에요. 스페인 세라믹."),
(J, "¡Ah, español! Ya decía yo, por el acento. Bienvenido a Bogotá. ¿Primera vez?", "아, 스페인 분! 억양 듣고 그럴 줄 알았어요. 보고타에 오신 걸 환영해요. 처음이세요?"),
(L, "Primera vez. Y ya noto algo raro. Subí la escalera del avión y me faltaba el aire.", "처음이에요. 그런데 벌써 뭔가 이상해요. 비행기 계단을 올라오는데 숨이 차더라고요."),
(J, "Es la altura, sumercé. Estamos a dos mil seiscientos metros. Tómese las cosas con calma los primeros días y beba mucha agüita.", "고도 때문이에요, 손님. 여기가 해발 2,600미터거든요. 처음 며칠은 천천히 하시고 물을 많이 드세요."),
(L, "Dos mil seiscientos... Y yo que pensaba que en Bogotá haría calor, como en Monterrey.", "2,600이라… 저는 보고타도 몬테레이처럼 더울 줄 알았어요."),
(J, "¡Qué va! Aquí no hay verano ni invierno. Por la mañana hace sol, por la tarde cae el aguacero, y por la noche hace frío. Todos los días.", "무슨 말씀을! 여긴 여름도 겨울도 없어요. 아침엔 해가 나고, 오후엔 소나기가 쏟아지고, 밤엔 추워요. 매일요."),
(L, "Cuatro estaciones en un día, entonces.", "그럼 하루에 사계절이 있는 거네요."),
(J, "Exacto. Por eso aquí todo el mundo lleva paraguas y chaqueta. Usted vino en camisa, ¿no?", "바로 그거예요. 그래서 여기선 다들 우산이랑 재킷을 들고 다녀요. 손님은 셔츠만 입고 오셨죠?"),
(L, "En camisa y sin paraguas. Muy de turista.", "셔츠만 입고 우산도 없이요. 완전 관광객이죠."),
(J, "No se preocupe, que hoy no se va a mojar: con este trancón llegamos al hotel justo antes del aguacero.", "걱정 마세요, 오늘은 안 젖으실 거예요. 이렇게 막히니 소나기 오기 직전에 딱 호텔에 도착할 거예요."),
(L, "¿Trancón? ¿Es un atasco?", "트랑콘이요? 교통 체증이요?"),
(J, "Eso, un atasco. En Bogotá el trancón es como el clima: todos los días, a la misma hora.", "네, 체증이요. 보고타에선 트랑콘도 날씨랑 같아요. 매일, 같은 시간에."),
(L, "¿Y qué me recomienda comer esta noche? Algo típico de aquí.", "오늘 저녁엔 뭘 먹으면 좋을까요? 여기 전통 음식으로요."),
(J, "Un ajiaco, sumercé. Sopa de papa con pollo, mazorca y guascas. Con este frío, le devuelve el alma al cuerpo.", "아히아코요, 손님. 닭고기, 옥수수, 과스카 풀을 넣은 감자 수프예요. 이 추위엔 몸에 영혼을 돌려줘요."),
(L, "Apuntado: ajiaco y chaqueta.", "적었어요. 아히아코하고 재킷."),
(None, "Suena el celular de Jairo. Él contesta con el manos libres.", "하이로의 휴대폰이 울린다. 그가 핸즈프리로 받는다."),
(J, "¿Aló? Sí, mijo. ¿Usted ya hizo la tarea? ... No, señor, primero la tarea y después el fútbol. ... Bueno, que Dios me lo bendiga.", "여보세요? 그래, 아들. 숙제는 하셨어요? … 아니요, 숙제 먼저 하고 축구는 그다음이에요. … 그래요, 하느님의 축복이 있기를."),
(L, "Perdone la pregunta... ¿le habla de usted a su hijo?", "실례지만… 아드님한테 '우스테드'로 말씀하세요?"),
(J, "Claro, sumercé. A mi hijo, a mi mamá, a mi señora. Aquí en Bogotá, en mi casa, todos nos hablamos de usted. Es por cariño, no por distancia.", "그럼요, 손님. 아들한테도, 어머니한테도, 아내한테도요. 여기 보고타에선, 우리 집에선 다들 서로 '우스테드'를 써요. 거리를 두려는 게 아니라 애정이에요."),
(L, "En España sería al revés. El usted es para los desconocidos y para los jefes.", "스페인에선 반대일 거예요. '우스테드'는 모르는 사람이랑 상사한테 쓰거든요."),
(J, "Pues aquí, si yo le digo «tú» a mi mamá, me mira como si le hubiera faltado al respeto. (ríe) Ya llegamos. Ese es su hotel.", "여기선 제가 어머니한테 '투'라고 하면, 무례하게 군 것처럼 쳐다보세요. (웃으며) 다 왔어요. 저기가 손님 호텔이에요."),
(L, "Muchas gracias, Jairo. ¿Mañana a las siete y media podría llevarme otra vez al aeropuerto?", "정말 고마워요, 하이로. 내일 7시 반에 다시 공항까지 태워 주실 수 있어요?"),
(J, "Con todo el gusto. Le dejo mi número. Y cómprese una chaqueta, ¿oyó? A la orden.", "기꺼이요. 제 번호 드릴게요. 그리고 재킷 하나 사 입으세요, 아셨죠? 언제든지요."),

("#", "Escena 2 · Lunes, 16:30 · Estudio de arquitectura de Camilo Restrepo, Usaquén", "장면 2 · 월요일 오후 4시 30분 · 우사켄의 카밀로 레스트레포 건축사무소"),
(None, "Una casa antigua de ladrillo, convertida en estudio. Maquetas blancas sobre mesas largas. Por la ventana se ven los cerros orientales, cubiertos de nubes. Una asistente joven recibe a Lucas.", "벽돌로 지은 오래된 집을 개조한 사무소. 긴 탁자 위에 흰 건축 모형들이 놓여 있다. 창밖으로 구름에 덮인 동쪽 산들이 보인다. 젊은 어시스턴트가 루카스를 맞는다."),
(D_, "Buenas tardes, señor Ferrer. Bienvenido. El arquitecto lo atiende en un momentico. ¿Le provoca un tintico mientras tanto?", "안녕하세요, 페레르 씨. 어서 오세요. 건축가님이 잠깐만 있으면 나오세요. 그동안 '틴티코' 한 잔 드시겠어요?"),
(L, "¿Un tinto? ¿A las cuatro y media? Bueno... si es costumbre, una copita.", "틴토요? 4시 반에요? 음… 그게 관습이라면 한 잔만요."),
(D_, "(sonríe) No, señor, un tinto es un café negro. Aquí el vino lo llamamos vino.", "(웃으며) 아니에요, 틴토는 블랙커피예요. 여기선 와인은 그냥 와인이라고 해요."),
(L, "Ah, perdone. Entonces sí, un tintico, por favor. Con mucho gusto.", "아, 죄송해요. 그럼 네, 틴티코 한 잔 부탁해요. 고맙습니다."),
(None, "Entra Camilo Restrepo: unos cuarenta y cinco años, gafas de pasta, chaqueta de lana. Le da la mano a Lucas con las dos manos.", "카밀로 레스트레포가 들어온다. 마흔다섯쯤, 뿔테 안경에 울 재킷 차림이다. 두 손으로 루카스와 악수한다."),
(C, "Señor Ferrer, qué pena con usted, lo hice esperar. Camilo Restrepo, a la orden. ¿Cómo le fue en el vuelo?", "페레르 씨, 기다리게 해서 정말 죄송해요. 카밀로 레스트레포입니다. 비행은 어떠셨어요?"),
(L, "Muy bien, gracias. Lucas, por favor. Y no se preocupe, acabo de llegar. Marta Ortiz me ha hablado muy bien de usted.", "아주 좋았어요, 고맙습니다. 루카스라고 불러 주세요. 그리고 걱정 마세요, 저도 방금 왔어요. 마르타 오르티스가 선생님 칭찬을 많이 하더군요."),
(C, "Marta es muy querida. Nos conocimos en la feria de Valencia hace tres años. Siga, siga, por favor. Siéntese.", "마르타는 참 좋은 사람이죠. 3년 전 발렌시아 박람회에서 만났어요. 들어오세요, 어서요. 앉으세요."),
(L, "Gracias. Le he traído algunas muestras. Pesan un poco, el taxista creía que traía piedras.", "고맙습니다. 샘플을 좀 가져왔어요. 조금 무거워서 택시 기사가 돌을 가져온 줄 알더라고요."),
(C, "(ríe) Y no se equivocaba: el porcelánico es piedra, al fin y al cabo. ¿Me regala un minutico para verlas con luz natural?", "(웃으며) 틀린 말도 아니죠. 결국 자기질 타일도 돌이니까요. 자연광에서 보게 잠깐만 시간을 내주시겠어요?"),
(None, "Camilo lleva una pieza del Blanco San Pedro junto a la ventana y la mira en silencio, girándola.", "카밀로가 '블랑코 산페드로' 한 장을 창가로 가져가 말없이 이리저리 돌려 본다."),
(C, "¿Y esta silueta, dentro de la veta? ¿Es una montaña?", "그리고 이 실루엣은요, 결 안에 있는 거요? 산인가요?"),
(L, "Es el Cerro de la Silla, en Monterrey. Nuestra diseñadora lo escondió en el mármol para un hotel de allí.", "몬테레이의 세로 데 라 시야예요. 저희 디자이너가 그곳 호텔을 위해 대리석 속에 숨겨 넣었어요."),
(C, "Precioso. Tal vez podamos hacer algo parecido con Monserrate. Pero primero, déjeme contarle mis proyectos, si me lo permite.", "정말 아름답네요. 어쩌면 몬세라테 산으로 비슷한 걸 할 수 있을지도 모르겠어요. 하지만 먼저 괜찮으시다면 제 프로젝트를 설명해 드릴게요."),
(L, "¿Monserrate?", "몬세라테요?"),
(C, "El cerro con la iglesia blanca, ahí arriba. Desde aquí no se ve por las nubes, pero todo bogotano lo lleva en la cabeza.", "저 위에 흰 성당이 있는 산이에요. 구름 때문에 여기선 안 보이지만, 보고타 사람은 다들 머릿속에 그 산을 품고 살아요."),
(L, "Nuria, nuestra diseñadora, estaría encantada. Le encantan los encargos con historia.", "저희 디자이너 누리아가 아주 좋아할 거예요. 사연 있는 주문을 좋아하거든요."),
(L, "Por favor. Para eso he venido.", "부탁드려요. 그러려고 왔어요."),
(C, "Son dos. El primero, un edificio de oficinas en la calle noventa y tres: dieciocho mil metros cuadrados de piso. El segundo, más importante, una clínica en el norte de la ciudad: unos veinticinco mil.", "두 개예요. 첫째는 93번가의 오피스 빌딩, 바닥 면적 1만 8천㎡. 둘째가 더 중요한데, 시 북쪽의 병원이에요. 2만 5천㎡쯤 돼요."),
(L, "¿Una clínica? Eso tiene exigencias muy concretas.", "병원이요? 그건 요구 사항이 아주 까다롭죠."),
(C, "Muchísimas. Necesitamos un material de muy baja absorción, que se limpie con productos fuertes todos los días, y con las mínimas juntas posibles. En un hospital, cada junta es un lugar donde se esconden las bacterias.", "아주 많아요. 흡수율이 아주 낮고, 매일 독한 세제로 닦아도 되고, 줄눈은 최대한 적어야 해요. 병원에선 줄눈 하나하나가 세균이 숨는 곳이거든요."),
(L, "Por eso el gran formato. Con placas de ciento veinte por doscientos sesenta, las juntas se reducen muchísimo.", "그래서 대형 규격이죠. 120×260짜리 판을 쓰면 줄눈이 확 줄어요."),
(C, "Exacto. Y en las zonas húmedas, antideslizante. Tal vez haga falta una certificación especial; eso todavía lo estamos estudiando.", "바로 그거예요. 그리고 물기 있는 구역엔 미끄럼 방지요. 어쩌면 특별 인증이 필요할지도 몰라요. 그건 아직 검토 중이에요."),
(L, "Eso lo tenemos. En Monterrey vamos a poner seis mil metros de antideslizante en las terrazas de unas torres.", "그건 있어요. 몬테레이에선 아파트 테라스에 미끄럼 방지 타일 6천㎡를 깔 거예요."),
(C, "¿Seis mil? Entonces ya tienen experiencia en proyectos grandes en América Latina.", "6천이요? 그럼 라틴아메리카 대형 프로젝트 경험이 이미 있으신 거네요."),
(L, "Estamos empezando. Le seré sincero: es nuestro primer proyecto grande fuera de Europa.", "이제 시작이에요. 솔직히 말씀드리면 유럽 밖에서는 첫 대형 프로젝트예요."),
(C, "Mejor así. Prefiero un proveedor que empieza con hambre que uno que ya está cansado.", "그게 더 좋아요. 지친 공급업체보다 배고픈 상태로 시작하는 업체가 좋아요."),
(L, "¿Y los plazos?", "일정은요?"),
(C, "La licitación de la clínica se abre en septiembre. Las oficinas van antes: quizás en junio ya estemos pidiendo cotizaciones.", "병원 입찰은 9월에 열려요. 오피스는 그보다 빨라서, 어쩌면 6월쯤엔 견적을 받고 있을 거예요."),
(L, "Septiembre nos daría tiempo para preparar una propuesta seria. ¿Quién importa normalmente este tipo de material en Colombia?", "9월이면 제대로 된 제안을 준비할 시간이 되겠네요. 콜롬비아에선 보통 누가 이런 자재를 수입하나요?"),
(C, "Y el precio, claro. ¿Tienen ya una idea de precio puesto en Bogotá?", "그리고 가격도요, 물론. 보고타 도착 기준 가격 감은 있으세요?"),
(L, "Todavía no. El puerto sería Cartagena, y luego el camión hasta aquí arriba. Tendría que calcularlo con nuestro director financiero.", "아직요. 항구는 카르타헤나일 거고, 거기서 여기까지 트럭으로 올라와야죠. 재무이사와 계산해 봐야 해요."),
(C, "Tómese su tiempo. Tal vez le convenga hablar antes con el distribuidor del que le voy a hablar.", "천천히 하세요. 제가 말씀드릴 유통업체와 먼저 얘기해 보시는 게 나을지도 몰라요."),
(C, "Distribuidores, casi siempre. Yo especifico el material, pero no compro. Conozco a uno muy serio, en Medellín. Si quiere, le colaboro con el contacto.", "거의 항상 유통업체예요. 저는 자재를 지정할 뿐 구매는 안 해요. 메데인에 아주 믿을 만한 업체를 하나 알아요. 원하시면 연락처를 연결해 드릴게요."),
(L, "Se lo agradecería mucho. Aunque... tengo que ser honesto con usted.", "정말 고맙겠어요. 그런데… 솔직하게 말씀드려야 할 게 있어요."),
(D_, "(entra con una bandeja) Su tintico, señor Ferrer. Y unas almojábanas, recién hechas.", "(쟁반을 들고 들어오며) 틴티코 나왔습니다, 페레르 씨. 그리고 갓 구운 알모하바나도요."),
(L, "Muchas gracias, Daniela. ¿Almojábanas?", "고마워요, 다니엘라. 알모하바나요?"),
(D_, "Pancitos de queso. Con el tinto son lo mejor de la tarde.", "치즈 빵이에요. 틴토랑 같이 먹으면 오후의 최고 간식이에요."),
(C, "Dígame, con toda confianza.", "편하게 말씀하세요."),
(L, "Estamos negociando un acuerdo de distribución en México. Todavía no está firmado, y Colombia no forma parte de él. Pero no quiero que haya sorpresas.", "멕시코에서 유통 계약을 협상하고 있어요. 아직 서명 전이고, 콜롬비아는 거기에 포함돼 있지 않아요. 하지만 나중에 놀라실 일이 없었으면 해요."),
(C, "Le agradezco la franqueza. Aquí eso se valora mucho. Colombia no es México, Lucas. Tal vez su socio mexicano piense lo contrario, pero aquí los arquitectos preferimos tratar con alguien de confianza en el país.", "솔직하게 말씀해 주셔서 고마워요. 여기선 그걸 아주 중요하게 여겨요. 콜롬비아는 멕시코가 아니에요, 루카스. 멕시코 파트너는 생각이 다를지도 모르지만, 여기 건축가들은 이 나라 안의 믿을 만한 사람과 일하는 걸 좋아해요."),
(None, "Suena el celular de Camilo. Mira la pantalla y sonríe.", "카밀로의 휴대폰이 울린다. 화면을 보더니 미소 짓는다."),
(C, "Perdóneme un segundico, es mi mamá. ¿Aló? Sí, mamita. ¿Usted ya almorzó? ... Sí, señora, esta noche paso por allá. ... Bueno, cuídese mucho. Chao.", "잠깐만 실례할게요, 어머니예요. 여보세요? 네, 엄마. 점심은 드셨어요? … 네, 오늘 밤에 들를게요. … 네, 몸조심하세요. 안녕히 계세요."),
(L, "El taxista también le hablaba de usted a su hijo. Me ha sorprendido.", "택시 기사도 아들한테 '우스테드'를 쓰더라고요. 놀랐어요."),
(C, "En Bogotá y en Boyacá es muy normal. El «tú» aquí puede sonar a coqueteo, o a que uno está bravo. El usted es más cálido de lo que parece.", "보고타랑 보야카에선 아주 흔해요. 여기서 '투'는 작업 거는 것처럼, 아니면 화난 것처럼 들릴 수 있어요. '우스테드'는 보기보다 따뜻한 말이에요."),
(L, "Entonces, ¿le hablo de usted o de tú?", "그럼 선생님한테 '우스테드'로 말할까요, '투'로 말할까요?"),
(C, "De usted, si no le molesta. Y yo a usted también. Así nos entendemos mejor.", "괜찮으시면 '우스테드'로요. 저도 그렇게 할게요. 그게 서로 더 잘 통해요."),
(D_, "Arquitecto, perdón: la gente de la clínica pregunta si puede llamarlos mañana a las diez.", "건축가님, 죄송해요. 병원 쪽에서 내일 10시에 전화해도 되는지 물어요."),
(C, "Dígales que sí, Daniela, que con mucho gusto. Lucas, ¿usted ya estará en el avión?", "괜찮다고 해 줘요, 다니엘라. 기꺼이요. 루카스, 그때쯤이면 비행기에 계시겠죠?"),
(L, "Sí, a las diez ya estaré volando hacia Monterrey. Pero podemos hacer una videollamada la semana que viene.", "네, 10시면 몬테레이행 비행기 안일 거예요. 하지만 다음 주에 화상 통화를 할 수 있어요."),
(C, "Perfecto. Le pido una cosa: déjeme una pieza del Blanco San Pedro. Quiero enseñársela al director de la clínica. Quizás le guste tanto como a mí.", "좋아요. 하나만 부탁할게요. '블랑코 산페드로' 한 장만 두고 가 주세요. 병원장한테 보여 주고 싶어요. 어쩌면 저만큼 좋아할지도 몰라요."),
(L, "Quédesela. Y le mando las fichas técnicas esta noche, con los valores de absorción y de resistencia química.", "가지세요. 그리고 오늘 밤에 흡수율과 내화학성 수치가 담긴 기술 사양서를 보내 드릴게요."),
(C, "Muy amable. Y si quiere, quédese a las onces. A las cinco tomamos chocolate con queso.", "고마워요. 그리고 괜찮으시면 '온세스'까지 계시다 가세요. 5시에 치즈를 넣은 초콜릿을 마셔요."),
(L, "¿Chocolate con queso? ¿El queso dentro del chocolate?", "치즈 넣은 초콜릿이요? 초콜릿 안에 치즈를 넣어요?"),
(C, "Dentro, sí. Se derrite y se come con cuchara. Es lo más bogotano que hay. Si lo prueba, ya es medio rolo.", "안에요, 네. 녹으면 숟가락으로 떠먹어요. 그게 가장 보고타다운 거예요. 맛보시면 반쯤은 보고타 사람이 되는 거죠."),
(L, "Pues entonces me quedo. Por la cultura.", "그럼 있을게요. 문화 체험으로요."),
(C, "Ah, y una última cosa, Lucas: aquí, a las cinco y media, empieza a llover fuerte. ¿Trajo paraguas?", "아, 그리고 마지막으로, 루카스. 여기선 5시 반이면 비가 세차게 와요. 우산 가져오셨어요?"),
(L, "No. Ya me lo ha dicho el taxista. Dos veces.", "아니요. 택시 기사도 그 말을 했어요. 두 번이나요."),
(C, "(le tiende uno) Tenga, le regalo este. Para que se acuerde de Bogotá cada vez que llueva en Onda.", "(우산 하나를 건네며) 자, 이거 드릴게요. 온다에 비가 올 때마다 보고타를 기억하시라고요."),
(L, "En Onda llueve muy poco. Así que lo guardaré como un tesoro.", "온다엔 비가 거의 안 와요. 그러니 보물처럼 간직할게요."),

("#", "Escena 3 · Lunes, 21:00 · Habitación del hotel — videollamada con Monterrey", "장면 3 · 월요일 밤 9시 · 호텔 방 — 몬테레이와 화상 통화"),
(None, "Fuera llueve con fuerza. Lucas, con el paraguas de Camilo apoyado en la pared, abre el portátil. En Monterrey son las ocho de la noche. Amparo aparece en la pantalla, con el pelo recogido y polvo de cemento en la camisa.", "밖에는 비가 세차게 내린다. 루카스는 카밀로의 우산을 벽에 기대 놓고 노트북을 연다. 몬테레이는 밤 8시다. 화면에 머리를 질끈 묶고 셔츠에 시멘트 가루가 묻은 암파로가 나타난다."),
(A, "Hola. Perdona la pinta. Acabo de volver de la obra.", "안녕하세요. 꼴이 이래서 미안해요. 방금 현장에서 돌아왔어요."),
(L, "Hola. ¿Cómo han ido las pruebas?", "안녕하세요. 테스트는 어떻게 됐어요?"),
(A, "Antes de nada: ¿has comido? Tienes cara de cansado.", "그 전에, 밥은 먹었어요? 피곤해 보여요."),
(L, "He tomado chocolate con queso. Aquí lo llaman «las onces». Y luego un ajiaco. Estoy bien.", "치즈 넣은 초콜릿을 마셨어요. 여기선 '온세스'라고 하더라고요. 그리고 아히아코도 먹었어요. 괜찮아요."),
(A, "Bien. El adhesivo que usa Rodolfo funciona con nuestras placas. La planitud, perfecta. El único problema son los colocadores: nunca habían trabajado con un formato tan grande.", "좋았어요. 로돌포가 쓰는 접착제가 우리 판이랑 잘 맞아요. 평탄도도 완벽하고요. 문제는 시공 기술자들뿐이에요. 이렇게 큰 규격은 다뤄 본 적이 없대요."),
(L, "¿Y eso se soluciona?", "그건 해결돼요?"),
(A, "Con formación. He pensado que Pepe podría mandar a alguien de Onda una semana, cuando llegue el primer contenedor.", "교육으로요. 첫 컨테이너가 도착하면 페페가 온다에서 누군가를 일주일 정도 보내면 어떨까 생각했어요."),
(L, "Muy buena idea. Se lo propongo a Vicente.", "아주 좋은 생각이에요. 비센테한테 제안할게요."),
(A, "Ya se lo he propuesto yo. (pausa) ¿Y tú? ¿Qué tal Bogotá?", "제가 벌써 제안했어요. (잠시 멈춤) 당신은요? 보고타는 어때요?"),
(L, "Ah. Bien hecho.", "아. 잘했어요."),
(A, "Me ha dicho que sí, si tú estás de acuerdo. Como somos los dos responsables del proyecto...", "당신이 동의하면 좋대요. 우리 둘이 이 프로젝트 공동 책임자니까…"),
(L, "Claro que estoy de acuerdo.", "당연히 동의하죠."),
(L, "Muy interesante. Dos proyectos: oficinas y una clínica. Más de cuarenta mil metros en total. Y el arquitecto ha visto el Blanco San Pedro y quiere hacer algo parecido con una montaña de aquí.", "아주 흥미로워요. 프로젝트가 두 개예요. 오피스하고 병원. 합쳐서 4만㎡가 넘어요. 그리고 건축가가 '블랑코 산페드로'를 보더니 여기 산으로 비슷한 걸 하고 싶대요."),
(A, "Cuarenta mil. Casi lo mismo que las torres. ¿Y Alejandra sabe algo?", "4만이라. 아파트랑 거의 같네요. 알레한드라는 뭐 좀 알아요?"),
(L, "Solo que he venido. No le he contado nada más.", "제가 여기 온 것만요. 그 이상은 아무 말도 안 했어요."),
(A, "Pues tal vez deberías hacerlo antes de que se entere por otro lado. Aquí todo el mundo se conoce, Lucas.", "그럼 다른 데서 듣기 전에 말하는 게 좋을지도 몰라요. 여기선 다들 서로 알아요, 루카스."),
(L, "Lo haré cuando vuelva. Mañana a mediodía estoy allí.", "돌아가서 할게요. 내일 정오면 거기 도착해요."),
(A, "Mañana, entonces. Y Lucas...", "그럼 내일이요. 그리고 루카스…"),
(L, "¿Sí?", "네?"),
(A, "Nada. Que la próxima vez que vayas a abrir un país, me gustaría saberlo antes que Alejandra.", "아무것도 아니에요. 다음에 나라 하나를 열러 갈 땐, 알레한드라보다 내가 먼저 알았으면 좋겠어요."),
(L, "Lo has sabido antes que ella. Te lo dije en el bautizo.", "그녀보다 먼저 알았잖아요. 세례식에서 말했잖아요."),
(A, "Me lo dijiste delante de ella. No es lo mismo.", "그녀 앞에서 말했죠. 그건 같지 않아요."),
(A, "Vale. (bosteza) Perdona. Llevo de pie desde las seis. Buenas noches, Lucas.", "알았어요. (하품하며) 미안해요. 6시부터 서 있었거든요. 잘 자요, 루카스."),

("#", "Escena 4 · Martes, 7:40 · Taxi de Jairo, camino de El Dorado", "장면 4 · 화요일 오전 7시 40분 · 엘도라도로 가는 하이로의 택시"),
(None, "Amanece despejado. Los cerros brillan al sol. Lucas lleva una chaqueta de lana nueva y el paraguas de Camilo.", "날이 맑게 갰다. 동쪽 산들이 햇빛에 반짝인다. 루카스는 새로 산 울 재킷을 입고 카밀로의 우산을 들었다."),
(J, "¡Buenos días, sumercé! ¡Mírelo, con chaqueta y paraguas! Ya parece rolo.", "좋은 아침이에요, 손님! 이것 봐, 재킷에 우산까지! 이제 보고타 사람 같네요."),
(L, "¿Rolo?", "롤로요?"),
(J, "Así nos dicen a los de Bogotá. ¿Qué tal le fue con el negocio?", "보고타 사람을 그렇게 불러요. 사업은 어떻게 됐어요?"),
(L, "Antes de eso: ayer probé el ajiaco y el chocolate con queso. Me siento medio rolo, como dice el arquitecto.", "그 전에, 어제 아히아코랑 치즈 초콜릿을 먹어 봤어요. 건축가 말대로 반쯤 보고타 사람이 된 기분이에요."),
(J, "¡Eso! Ya le falta solo hablarle de usted a su mamá.", "그거예요! 이제 어머니한테 '우스테드'로 말하는 것만 남았네요."),
(L, "Bien, creo. Quizás vuelva en septiembre. Si todo sale bien.", "잘된 것 같아요. 어쩌면 9월에 다시 올지도 몰라요. 다 잘되면요."),
(J, "Ojalá que sí. Y si vuelve, me llama. Yo lo recojo, aunque esté lloviendo a cántaros.", "꼭 그러시길. 다시 오시면 전화 주세요. 비가 억수같이 쏟아져도 모시러 갈게요."),
(None, "Vibra el móvil de Lucas. Un correo de la oficina del licenciado Treviño, con copia a Alejandra Garza. Asunto: «Contrato de distribución — borrador v2».", "루카스의 휴대폰이 진동한다. 트레비뇨 변호사 사무실에서 온 메일이다. 알레한드라 가르사가 참조로 들어가 있다. 제목: '유통 계약서 — 초안 2차'."),
(L, "(lee en voz baja) «Cláusula tercera. Territorio: el Distribuidor tendrá la exclusividad de los Productos en México, Centroamérica, Colombia y el resto de América Latina...».", "(작게 읽으며) '제3조. 영역: 유통사는 멕시코, 중미, 콜롬비아 및 그 밖의 라틴아메리카 전역에서 본 제품에 대한 독점권을 가진다…'"),
(J, "¿Todo bien, sumercé? Se quedó callado.", "괜찮으세요, 손님? 갑자기 조용해지셨네요."),
(L, "Sí... Bueno, no lo sé. Alguien quiere más de lo que habíamos hablado.", "네… 아니, 잘 모르겠어요. 누가 우리가 얘기했던 것보다 더 많은 걸 원하네요."),
(J, "Eso pasa mucho en la vida, sumercé. Uno ofrece la mano y le cogen el codo. Bueno, aquí decimos «el codo»; usted me entiende.", "인생에선 그런 일이 흔하죠, 손님. 손을 내밀면 팔꿈치까지 잡으려 들거든요. 뭐, 여기선 '팔꿈치'라고 해요. 무슨 말인지 아시죠."),
(L, "(sonríe por fin) Le entiendo perfectamente, Jairo. Y me alegra oír «coger» sin que nadie se ponga rojo.", "(드디어 미소 지으며) 완벽하게 이해해요, 하이로. 그리고 아무도 얼굴 붉히지 않고 '코헤르'를 듣게 돼서 기쁘네요."),
(J, "¿Rojo? ¿Por qué se iba a poner rojo nadie?", "얼굴을 붉혀요? 왜 누가 얼굴을 붉혀요?"),
(L, "Es una larga historia. De México. Se la cuento en septiembre.", "얘기가 길어요. 멕시코 얘기예요. 9월에 해 드릴게요."),
(J, "Trato hecho. Ya llegamos. Que tenga muy buen viaje. A la orden siempre.", "약속했어요. 다 왔어요. 즐거운 여행 되세요. 언제든지 불러 주세요."),
(None, "Lucas baja del taxi y mira otra vez la pantalla: «...y el resto de América Latina». Guarda el móvil, sujeta fuerte el paraguas y entra en la terminal.", "루카스가 택시에서 내려 다시 화면을 본다. '…그 밖의 라틴아메리카 전역.' 휴대폰을 넣고 우산을 꽉 쥔 채 터미널로 들어간다."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "암파로를 몬테레이 현장에 남겨 두고 루카스는 혼자 보고타에 도착한다. 해발 2,600미터, 오후마다 소나기가 쏟아지는 도시에서 그는 택시 기사 하이로에게 날씨와 '가족끼리도 쓰는 usted'을 배우고, ICEX의 마르타가 소개한 건축가 카밀로 레스트레포를 만난다. 카밀로의 오피스와 병원 프로젝트는 대형 타일에 딱 맞는 일이다. 그날 밤 화상 통화 속 암파로의 목소리는 차분하지만 차갑고, 다음 날 아침 공항 가는 택시 안에서 루카스는 멕시코에서 온 새 계약 초안의 한 줄 앞에서 멈춘다.",
 "듣기 질문 ① 보고타 사람들이 가족끼리도 usted를 쓰는 이유를 하이로와 카밀로는 어떻게 설명했나?",
 "듣기 질문 ② 카밀로의 두 프로젝트는 무엇이며, 병원에 대형 타일이 맞는 이유는?",
 "듣기 질문 ③ 트레비뇨의 새 계약 초안 제3조는 무엇을 바꾸었나?",
]),
]

